onClick:
{{(async()=>{
  const g=appsmith.store.selected_vendor_group||{};
  const id=String(g.RFQ_GROUP_ID||g.groupId||g.GROUP_ID||'default');
  const stages={...(appsmith.store.rfq_group_stages||{})};
  stages[id]='enfa';
  await storeValue('rfq_group_stages',stages,true);
  await storeValue('viewing_stage_id','enfa',true);
  if(typeof js_NFAController!=='undefined' && js_NFAController.syncGroupState){
    await js_NFAController.syncGroupState(id);
  }
  return js_NavigationController.handleStageSelect('enfa');
})()}}
